00045 std::istream &operator>>(std::istream &in, Upsample &v) {
00046     std::string s;
00047     in >> s;
00048     s = lowercase(s);
00049 
00050     if (s == "nearest")
00051         v = Upsample_Nearest;
00052     else if (s == "linear")
00053         v = Upsample_Linear;
00054     else if (s == "cubic")
00055         v = Upsample_Cubic;
00056     else if (s == "modifiedcubic")
00057         v = Upsample_ModifiedCubic;
00058     else if (s == "adaptivecubic")
00059         v = Upsample_AdaptiveCubic;
00060     else
00061         ERR("not an upsampler: %s", s.c_str());
00062     return in;
00063 }
00064 
